        'albani_score_outside':      'Non compté (segment en anglais)',
        'albani_score_outside_monologue': 'Écarté de ce décompte (segment de dialogue ou en anglais)',
        'albani_score_words':        '{words} mots',
        'albani_score_listen':       'Cliquer pour écouter',
        'albani_pairs_tooltip':      '{count} rencontres',
        'albani_pairs_tooltip_one':  '{count} rencontre',
        'albani_keyness_cards':      'Les mots-signatures',
        'albani_keyness_cards_desc': 'Les mots que chaque enregistrement, période ou type de segment emploie bien plus que les autres enregistrements, les plus marquants en plus grand. Survolez un mot pour voir combien de fois il est plus fréquent, et les nombres qui le justifient.',
        'albani_keyness_only_here':  'seulement ici',
        'albani_formulae_spread':    'dans {count} enregistrements sur {total}',
        'albani_formulae_spread_one': 'dans {count} enregistrement sur {total}',
        'albani_formulae_strip_key': 'Chaque bande compte une case par enregistrement, du plus ancien daté aux non-datés. Plus la case est foncée, plus la formule y revient souvent pour 10 000 mots, et une case vide signifie qu’elle n’y est jamais prononcée.',
        'albani_formulae_cell':      '{count} fois, {rate} pour 10 000 mots',
